+    expect(nav).toMatch(new RegExp(`height:\\s*${height}\\s*\\+\\s*insets\\.bottom`));
+    if (name === 'CoachNavigator.tsx') expect(nav).toMatch(/paddingBottom:\s*4\s*\+\s*insets\.bottom/);
